
import { NextResponse } from "next/server";
import Database from "better-sqlite3";
import path from "path";
import { generateSecureClientToken } from "../../../utils/tokenAuth.js";
import { sendClientPortalEmail } from "../../../utils/emailDispatcher.js";

export async function POST(request) {
  try {
    const body = await request.json();
    const { id, currentPhase, progress, cureStatus, clientEmail, clientName } = body;

    if (!id || !currentPhase) {
      return NextResponse.json({ error: "Project ID and current phase are required" }, { status: 400 });
    }

    const clientToken = generateSecureClientToken(id);
    const dbPath = path.join(process.cwd(), "api", "database.sqlite");
    const db = new Database(dbPath);

    const sql = "INSERT OR REPLACE INTO projects (id, client_token, current_phase, progress, cure_status, created_at) VALUES (?, ?, ?, ?, ?, ?)";
    const insert = db.prepare(sql);

    insert.run(
      id,
      clientToken,
      currentPhase,
      progress || 0,
      cureStatus || "Initialized",
      new Date().toISOString()
    );

    const dashboardUrl = `/dashboard?token=${clientToken}`;

    let emailResult = { success: false, skipped: true };
    if (clientEmail) {
      emailResult = await sendClientPortalEmail({
        clientEmail,
        clientName,
        dashboardUrl
      });
    }

    return NextResponse.json({ 
      success: true, 
      projectId: id, 
      clientToken,
      dashboardUrl,
      emailResult
    });
  } catch (error) {
    return NextResponse.json({ error: "Failed to create project and dispatch email", details: error.message }, { status: 500 });
  }
}

